Algorithm Congelar
  Define notas As Vector<Integer> <- vector();
  notas.append(7);
  Define foto As Immutable<Vector<Integer>> <- snapshot(notas);
  notas.append(9);
  Write foto.length(), " ", notas.length(), " ", foto[0];
EndAlgorithm

Algorithm EscribirFoto
  Define notas As Vector<Integer> <- vector();
  Define foto As Immutable<Vector<Integer>> <- snapshot(notas);
  foto.append(9);
EndAlgorithm
